-- test_seguridad_imagenes.sql — tests unitarios del pipeline de seguridad de imágenes
-- Tarea t_ac7aeaca. SOLO entorno de pruebas. Todo corre en una transacción con ROLLBACK.
-- Uso: psql -h HOST -U svc_postgrest_admin -d kambalache -f test_seguridad_imagenes.sql
-- Salida: tabla de resultados (nombre, obtenido, esperado, paso). Exigir paso=t en todas.
\set ON_ERROR_STOP on
BEGIN;
SET request.jwt.claims = '{"sub":"20000000-0000-4000-8000-0000000000d3","role":"seller"}';

CREATE TEMP TABLE _t(nombre text, esperado text, obtenido text, paso boolean);

-- helper implícito: cada test inserta una fila
INSERT INTO _t VALUES
