 ('estructura png+EICAR tras IEND', 'ERR:png_bytes_tras_iend', auth.validar_estructura_imagen(decode('89504e470d0a1a0a0000000d4948445200000002000000020802000000fdd49a730000001649444154789c633c2127c7c0c0c0c4c0c0c0c0c000000d0401087d71ca660000000049454e44ae42608258354f2150254041505b345c505a58353428505e2937434329377d2445494341522d5354414e444152442d414e544956495255532d544553542d46494c452124482b482a','hex'), 'image/png'), NULL),
