 ('estructura jpeg limpio', 'OK', auth.validar_estructura_imagen(decode('','hex'), 'image/jpeg'), NULL),
 ('estructura jpeg padding 0x00 tolerado', 'OK', auth.validar_estructura_imagen(decode('','hex'), 'image/jpeg'), NULL),
 ('estructura jpeg+EICAR tras EOI', 'ERR:jpeg_bytes_tras_eoi', auth.validar_estructura_imagen(decode('','hex'), 'image/jpeg'), NULL),
 ('estructura gif limpio', 'OK', auth.validar_estructura_imagen(decode('47494638376102000200810000c81e1e0000000000000000002c0000000002000200000806000108041010003b','hex'), 'image/gif'), NULL),
 ('estructura webp limpio', 'OK', auth.validar_estructura_imagen(decode('52494646400000005745425056503820340000001002009d012a0200020000800825a00274ba01f801f80003c800fefd01afffbef865bddbff75ffff73ddfdcf77f73ddffdcce000','hex'), 'image/webp'), NULL),
 ('clamav EICAR solo', 'INFECTADO', auth.scan_clamav(decode('58354f2150254041505b345c505a58353428505e2937434329377d2445494341522d5354414e444152442d414e544956495255532d544553542d46494c452124482b482a','hex')), NULL),
 ('clamav png limpio', 'OK', auth.scan_clamav(decode('89504e470d0a1a0a0000000d4948445200000002000000020802000000fdd49a730000001649444154789c633c2127c7c0c0c0c4c0c0c0c0c000000d0401087d71ca660000000049454e44ae426082','hex')), NULL);

-- re-encodeo: salida no nula, pasa estructura y magic-bytes (round-trip limpio)
INSERT INTO _t
SELECT 'sanitizar png limpio -> estructura OK', 'OK',
       auth.validar_estructura_imagen(auth.sanitizar_imagen(decode('89504e470d0a1a0a0000000d4948445200000002000000020802000000fdd49a730000001649444154789c633c2127c7c0c0c0c4c0c0c0c0c000000d0401087d71ca660000000049454e44ae426082','hex'), 'image/png'), 'image/png'), NULL;
INSERT INTO _t
SELECT 'sanitizar png+EICAR -> neutralizado (estructura OK)', 'OK',
       auth.validar_estructura_imagen(auth.sanitizar_imagen(decode('89504e470d0a1a0a0000000d4948445200000002000000020802000000fdd49a730000001649444154789c633c2127c7c0c0c0c4c0c0c0c0c000000d0401087d71ca660000000049454e44ae42608258354f2150254041505b345c505a58353428505e2937434329377d2445494341522d5354414e444152442d414e544956495255532d544553542d46494c452124482b482a','hex'), 'image/png'), 'image/png'), NULL;
INSERT INTO _t
SELECT 'sanitizar png+EICAR -> sin payload (sin \x4549434152)', '0',
       coalesce(position('\x4549434152'::bytea in auth.sanitizar_imagen(decode('89504e470d0a1a0a0000000d4948445200000002000000020802000000fdd49a730000001649444154789c633c2127c7c0c0c0c4c0c0c0c0c000000d0401087d71ca660000000049454e44ae42608258354f2150254041505b345c505a58353428505e2937434329377d2445494341522d5354414e444152442d414e544956495255532d544553542d46494c452124482b482a','hex'), 'image/png'))::text, '0'), NULL;
INSERT INTO _t
SELECT 'sanitizar jpeg limpio -> termina EOI ffd9', 'ffd9',
       encode(substring(auth.sanitizar_imagen(decode('','hex'), 'image/jpeg') from octet_length(auth.sanitizar_imagen(decode('','hex'), 'image/jpeg'))-1 for 2),'hex'), NULL;
INSERT INTO _t
SELECT 'sanitizar webp limpio -> estructura OK', 'OK',
       auth.validar_estructura_imagen(auth.sanitizar_imagen(decode('52494646400000005745425056503820340000001002009d012a0200020000800825a00274ba01f801f80003c800fefd01afffbef865bddbff75ffff73ddfdcf77f73ddffdcce000','hex'), 'image/webp'), 'image/webp'), NULL;
INSERT INTO _t
SELECT 'sanitizar gif limpio -> estructura OK', 'OK',
       auth.validar_estructura_imagen(auth.sanitizar_imagen(decode('47494638376102000200810000c81e1e0000000000000000002c0000000002000200000806000108041010003b','hex'), 'image/gif'), 'image/gif'), NULL;
INSERT INTO _t
SELECT 'sanitizar binario invalido -> NULL', 'true',
       (auth.sanitizar_imagen(decode('89504e470d0a1a0a0000000d4948445200000002000000020802000000fdd49a730000001649444154789c633c2127c7c0c0c0c4c0c0c0c0c000000d0401087d71ca660000000049454e44ae42608258354f2150254041505b345c505a58353428505e2937434329377d2445494341522d5354414e444152442d414e544956495255532d544553542d46494c452124482b482a','hex'), 'image/jpeg') IS NULL)::text, NULL;

-- RPC: imagen legítima pasa y se almacena SOLO la versión re-encodeada
DO $$
DECLARE
  v_id uuid; v_row auth.galeria_fotos%ROWTYPE;
BEGIN
  v_id := auth.seller_subir_imagen('b1000000-0000-4000-8000-00000000bb01',
        decode('89504e470d0a1a0a0000000d4948445200000002000000020802000000fdd49a730000001649444154789c633c2127c7c0c0c0c4c0c0c0c0c000000d0401087d71ca660000000049454e44ae426082','hex'), 'image/png', 'unit_ok.png', 'test unitario', false);
  SELECT * INTO v_row FROM auth.galeria_fotos WHERE id = v_id;
  INSERT INTO _t VALUES ('rpc png legítimo retorna uuid', 'true', (v_id IS NOT NULL)::text, NULL);
  INSERT INTO _t VALUES ('rpc almacena solo reencode (metadata sanitizado)', 'true', (v_row.metadata->>'sanitizado'), NULL);
  INSERT INTO _t VALUES ('rpc dato almacenado pasa estructura', 'OK',
        auth.validar_estructura_imagen(v_row.data_bytea, v_row.mime_type), NULL);
  INSERT INTO _t VALUES ('rpc tamano_bytes == bytes almacenados', 'true',
        (v_row.tamano_bytes = octet_length(v_row.data_bytea))::text, NULL);
END $$;

-- RPC: PNG+EICAR debe rechazarse con P0001
DO $$
BEGIN
  PERFORM auth.seller_subir_imagen('b1000000-0000-4000-8000-00000000bb01',
        decode('89504e470d0a1a0a0000000d4948445200000002000000020802000000fdd49a730000001649444154789c633c2127c7c0c0c0c4c0c0c0c0c000000d0401087d71ca660000000049454e44ae42608258354f2150254041505b345c505a58353428505e2937434329377d2445494341522d5354414e444152442d414e544956495255532d544553542d46494c452124482b482a','hex'), 'image/png', 'unit_evil.png', null, false);
  INSERT INTO _t VALUES ('rpc png+EICAR rechazado P0001', 'P0001', 'SIN_ERROR', NULL);
EXCEPTION WHEN raise_exception THEN
  INSERT INTO _t VALUES ('rpc png+EICAR rechazado P0001', 'P0001', 'P0001', NULL);
END $$;

-- RPC: JPEG con basura tras EOI debe rechazarse con P0001
DO $$
BEGIN
  PERFORM auth.seller_subir_imagen('b1000000-0000-4000-8000-00000000bb01',
        decode('','hex'), 'image/jpeg', 'unit_evil.jpg', null, false);
  INSERT INTO _t VALUES ('rpc jpeg+basura rechazado P0001', 'P0001', 'SIN_ERROR', NULL);
EXCEPTION WHEN raise_exception THEN
  INSERT INTO _t VALUES ('rpc jpeg+basura rechazado P0001', 'P0001', 'P0001', NULL);
END $$;

UPDATE _t SET paso = (obtenido = esperado);
TABLE _t;
SELECT count(*) FILTER (WHERE NOT paso) AS fallos, count(*) AS total FROM _t;

ROLLBACK;
